'use strict';
/* All learning content lives in this local JS file. No accounts, APIs, frameworks or tracking. */
const DATA_KEY='bea-complete-v1', LEGACY_KEY='bea-unit1-progress-v1';
const SKILLS=['Reading','Listening','Speaking','Writing','Grammar','Vocabulary'];
const TABS=[['overview','Overview'],['reading','📖 Reading'],['listening','🎧 Listening'],['speaking','🎙 Speaking'],['writing','✍ Writing'],['grammar','🧩 Grammar'],['vocab','🗂 Vocabulary'],['quiz','✅ Quiz']];
const MAX_ID=LESSONS.length;
const E=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const toWords=s=>String(s||'').trim().match(/[\p{L}\p{N}]+(?:['’\-][\p{L}\p{N}]+)*/gu)||[];
const countWords=s=>toWords(s).length;
const norm=s=>String(s).toLowerCase().normalize('NFKC').replace(/[’]/g,"'").replace(/[^\p{L}\p{N}' ]/gu,' ').replace(/\s+/g,' ').trim();
const today=()=>{let d=new Date();return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')};
const tr=(id)=>LESSONS.find(l=>l.id===Number(id));
const hasSkill=(l,s)=>(state.skills[l.id]||[]).includes(s);
const allDone=()=>state.passed.filter(n=>n>=1&&n<=MAX_ID).length;
const defaultState=()=>({passed:[],scores:{},skills:{},writing:{},cards:{},visited:[],last:1,speed:0.85,studyDates:[],mockResults:[]});
function loadState(){
  let s=defaultState();
  try{let saved=JSON.parse(localStorage.getItem(DATA_KEY)||'null');if(saved&&typeof saved==='object'&&!Array.isArray(saved)){
    for(let k of Object.keys(s))if(saved[k]!==undefined&&typeof saved[k]===typeof s[k])s[k]=saved[k];
  }
  let legacy=JSON.parse(localStorage.getItem(LEGACY_KEY)||'[]');if(Array.isArray(legacy))s.passed=[...new Set([...s.passed,...legacy.map(Number).filter(n=>n>=1&&n<=18)])];
  }catch(e){ /* Some local or privacy modes block storage; the site remains usable. */ }
  s.passed=Array.isArray(s.passed)?[...new Set(s.passed.map(Number).filter(n=>n>=1&&n<=MAX_ID))]:[];
  s.last=Math.max(1,Math.min(MAX_ID,Number(s.last)||1));
  for(let key of ['skills','scores','writing','cards'])if(!s[key]||typeof s[key]!=='object'||Array.isArray(s[key]))s[key]={};
  s.visited=Array.isArray(s.visited)?s.visited:[];
  s.studyDates=Array.isArray(s.studyDates)?s.studyDates:[];
  s.mockResults=Array.isArray(s.mockResults)?s.mockResults:[];
  return s;
}
let state=loadState();let timerHandle=null,timerEndsAt=0,timerRemain=0,recorder=null,recordedChunks=[],recordedAudioURL=null,recogniser=null;let activeFlash=null;let searchQuery='',filterLevel='all';let gymQuestions=[],gymLevel='all';
function save(){try{localStorage.setItem(DATA_KEY,JSON.stringify(state));localStorage.setItem(LEGACY_KEY,JSON.stringify(state.passed.filter(n=>n<=18)));}catch(e){toast('Browser storage unavailable. Export your progress as a backup.')}}
function recordVisit(id){if(!state.visited.includes(id))state.visited.push(id);state.last=id;let d=today();if(!state.studyDates.includes(d))state.studyDates.push(d);save()}
function markSkill(l,skill){let n=String(l.id),set=new Set(state.skills[n]||[]);set.add(skill);state.skills[n]=[...set];save();updateAside()}
function toast(message){let el=document.getElementById('toast');el.textContent=message;el.classList.add('show');clearTimeout(toast._t);toast._t=setTimeout(()=>el.classList.remove('show'),3500)}
function percent(n,d){return Math.round((n/(d||1))*100)}
function levelLessons(level){return LESSONS.filter(l=>l.level===level)}
function updateAside(){const done=allDone();const pct=percent(done,MAX_ID);document.getElementById('sideCount').textContent=`${done} / ${MAX_ID}`;document.getElementById('sidePercent').textContent=pct+'%';document.getElementById('sideFill').style.width=pct+'%';document.getElementById('sideTracks').innerHTML=TRACKS.map(([id,label])=>`<a href="#courses/${encodeURIComponent(id)}" data-track="${E(id)}"><span>${E(label)}</span><span>${state.passed.filter(n=>tr(n)?.level===id).length}/${levelLessons(id).length}</span></a>`).join('')}
function route(){let hash=decodeURIComponent(location.hash.replace(/^#/,''))||'home';let parts=hash.split('/');let top=parts[0];clearLessonTimer();if(!top)top='home';
 const app=document.getElementById('app');
 try{
  if(top==='home')app.innerHTML=renderHome();
  else if(top==='courses')app.innerHTML=renderCourses(parts[1]||'all');
  else if(top==='lesson') {let l=tr(parts[1]);app.innerHTML=l?renderLesson(l,parts[2]||'overview'):renderCourses('all');if(l)recordVisit(l.id)}
  else if(top==='review')app.innerHTML=renderReview();
  else if(top==='gym')app.innerHTML=renderGym(parts[1]||'all');
  else if(top==='ielts')app.innerHTML=renderIELTS();
  else if(top==='mock')app.innerHTML=renderMock(parts[1]);
  else if(top==='guide')app.innerHTML=renderGuide();
  else if(top==='updates')app.innerHTML=renderUpdates();
  else app.innerHTML=renderHome();
 }catch(e){console.error(e);app.innerHTML=`<div class="panel"><h2>Something went wrong</h2><p>Please reload the page. Your saved progress is kept in your browser.</p><code>${E(e.message)}</code></div>`}
 document.querySelectorAll('.toplinks a').forEach(a=>a.classList.toggle('active',a.dataset.nav=== (top==='lesson'?'courses':top==='mock'?'ielts':top)));
 document.querySelectorAll('.side-tracks a').forEach(a=>a.classList.toggle('active',a.dataset.track===parts[1]));
 document.querySelector('.toplinks').classList.remove('open');document.getElementById('menuToggle').setAttribute('aria-expanded','false');
 updateAside();window.scrollTo(0,0);if(top==='mock')startMockClock();}
function renderUpdates(){let entries=Array.isArray(SITE_META.history)?SITE_META.history:[];
 return `<div class="page"><div class="eyebrow">ACADEMY RELEASE HISTORY</div><h1>What's new in Burmese English Academy?</h1><p class="muted">Version ${E(SITE_META.version)} · Updated ${E(SITE_META.updated)} · ${MAX_ID} guided lessons</p><div class="notice"><strong>Our commitment:</strong> The learning materials are free. New lesson content and corrections will appear here when published.</div><div class="cards" style="display:block">${entries.map(entry=>`<article class="panel" style="margin:16px 0"><span class="level-pill">Version ${E(entry.version)}</span> <span class="muted">${E(entry.date)}</span><h2>${E(entry.title||'Website update')}</h2><p style="white-space:pre-line">${E(entry.notes||'Improvements and lesson updates.')}</p></article>`).join('')}</div><div class="panel"><h2>For learners | သင်ယူသူများအတွက်</h2><p>You do not need to download the website again to see newly published lessons. Just refresh this page while online.</p><p class="mm">သင်ခန်းစာအသစ် တင်ထားရင် Website ကို Refresh လုပ်ပြီး ကြည့်နိုင်ပါတယ်။</p><p class="note-small">Your learning progress remains in your own browser. Changing browsers or devices does not automatically transfer progress; use Study guide → Export progress for backup.</p></div></div>`;}
function renderHome(){let next=LESSONS.find(l=>!state.passed.includes(l.id))||LESSONS[MAX_ID-1];let studied=state.visited.length;let ready=state.mockResults.length;
 return `<div class="page"><section class="hero"><div class="eyebrow">FREE ENGLISH PRACTICE • ENGLISH + မြန်မာ</div><div class="release-flag">Official academy site · v${E(SITE_META.version)} · Updated ${E(SITE_META.updated)} <a href="#updates">See updates →</a></div><h1>From first words to <em>confident communication.</em></h1><p>${MAX_ID} guided lessons across A1, A2, B1, B2, C1 and IELTS preparation. Read, listen, speak, write, practise grammar and build vocabulary—all in one place.</p><p class="mm">နေ့စဉ်လေ့ကျင့်ပါ။ ကိုယ်တိုင်ပြော၊ ရေး၊ နားထောင်၊ ဖတ်ပြီး တဖြည်းဖြည်း တိုးတက်အောင်လုပ်ကြမယ်။</p><div class="hero-actions"><a href="#lesson/${next.id}/overview" class="btn light">${studied?'Continue learning':'Start learning'} → Lesson ${next.id}</a><a href="#courses" class="btn ghost">Explore all levels</a></div></section>
 <section class="metrics" aria-label="Your learning statistics"><div class="metric"><strong class="value">${MAX_ID}</strong><span class="label">Guided lessons</span></div><div class="metric"><strong class="value">${allDone()}</strong><span class="label">Passed quizzes</span></div><div class="metric"><strong class="value">${SKILLS.length}</strong><span class="label">Practise all six skills</span></div><div class="metric"><strong class="value">${state.studyDates.length}</strong><span class="label">Days with local activity</span></div></section>
 <div class="section-head"><div><span class="eyebrow">YOUR PLAN</span><h2>Make a little progress today</h2><p>Start with a manageable session, then review mistakes.</p></div></div><div class="welcome-work"><article class="panel"><h3>Next recommended lesson</h3><span class="level-pill">${E(next.level)}</span><h2 style="margin-top:12px">${E(next.title)}</h2><p class="mm mm-soft">${E(next.myanmarTitle)}</p><p>${E(next.summary)}</p><div class="toolbar-actions"><a href="#lesson/${next.id}/overview" class="btn primary">Open lesson ${next.id} →</a><a href="#review" class="btn outline">Review words</a></div></article><article class="panel"><h3>A 25-minute learning routine</h3><ol class="flow-steps"><li><span class="step-num">05</span><span>Review five useful words</span></li><li><span class="step-num">08</span><span>Read and listen for meaning</span></li><li><span class="step-num">07</span><span>Speak aloud and write a short response</span></li><li><span class="step-num">05</span><span>Check mistakes and retry</span></li></ol><p class="note-small mm">အချိန်နည်းနည်းပဲ ရလည်း ပုံမှန်လေ့ကျင့်ခြင်းက အရေးကြီးပါတယ်။</p></article></div>
 <div class="section-head"><div><span class="eyebrow">PATHWAY</span><h2>Choose your learning level</h2></div><a href="#courses">View every lesson →</a></div><section class="cards">${TRACKS.map(([id,label,mm],i)=>trackCard(id,label,mm,i)).join('')}</section>
 <div class="section-head"><div><span class="eyebrow">PRACTICE BALANCE</span><h2>Build all six skills</h2><p>Count of lessons where you completed a practice activity, not a verified ability score.</p></div><a href="#gym">Try Grammar Gym →</a></div><div class="meter-grid">${SKILLS.map(s=>`<div class="meter-item"><strong>${E(s)}</strong><span class="statline">${Object.values(state.skills).filter(a=>Array.isArray(a)&&a.includes(s)).length} lesson activities practised</span><div class="progress"><span style="width:${percent(Object.values(state.skills).filter(a=>Array.isArray(a)&&a.includes(s)).length,MAX_ID)}%"></span></div></div>`).join('')}</div>
 <div class="panel challenge"><h2>IELTS practice without confusion</h2><p>Academic and General Training are separate. You get original IELTS-style reading/listening exercises and timed writing tasks, but no automatically invented official band scores.</p><div class="toolbar-actions"><a class="btn primary" href="#ielts">Open IELTS Lab →</a><a class="btn outline" href="#guide">How to study well</a></div></div><div class="notice amber"><strong>Learning promise:</strong> These exercises provide structured practice, not guaranteed fluency, a C1 certificate or an IELTS band score. Speaking and writing still benefit from human feedback and genuine examination practice.</div></div>`}
function trackCard(id,label,mm,index){let ls=levelLessons(id),done=ls.filter(l=>state.passed.includes(l.id)).length;return `<article class="card track-card"><div><span class="level-pill ${index>=5?'purple':index>=3?'blue':''}">${E(id)}</span><h3>${E(label)}</h3><p class="mm">${E(mm)}</p><span class="track-count">${ls.length} lessons · ${done} quizzes passed</span></div><div class="progress"><span style="width:${percent(done,ls.length)}%"></span></div><div class="card-bottom"><span class="statline">${percent(done,ls.length)}% quiz completion</span><a href="#courses/${encodeURIComponent(id)}" class="btn soft sm">Explore →</a></div></article>`}
function renderCourses(level){filterLevel=level==='all'?'all':TRACKS.some(t=>t[0]===level)?level:'all';const all=LESSONS.filter(l=>(filterLevel==='all'||l.level===filterLevel)&&(`${l.title} ${l.myanmarTitle} ${l.summary} ${l.level}`).toLowerCase().includes(searchQuery.toLowerCase()));
 return `<div class="page"><div class="eyebrow">THE FULL LEARNING PATHWAY</div><h1>Explore ${MAX_ID} lessons.</h1><p class="muted">Use the level filter or search. All lessons are unlocked; follow the order for a stronger foundation.</p><div class="toolbar"><input id="courseSearch" class="search" type="search" autocomplete="off" placeholder="Search lessons, topics…" value="${E(searchQuery)}" aria-label="Search lessons"><select class="filter" id="levelSelect" aria-label="Filter course level"><option value="all">All levels</option>${TRACKS.map(t=>`<option value="${E(t[0])}" ${filterLevel===t[0]?'selected':''}>${E(t[0])} — ${E(t[1])}</option>`).join('')}</select></div><div id="courseMatches" class="lesson-list">${all.length?all.map(lessonTile).join(''):'<p class="empty">No lessons match your search. Try a different keyword.</p>'}</div><div class="notice" style="margin-top:23px">A level label describes the intended complexity of the practice material; completing a short module is not proof of CEFR proficiency.</div></div>`}
function lessonTile(l){let passed=state.passed.includes(l.id),skills=(state.skills[l.id]||[]).length;return `<a class="lesson-item" href="#lesson/${l.id}/overview"><span class="lesson-index">${String(l.id).padStart(2,'0')}</span><div class="lesson-info"><h3>${E(l.title)}</h3><p class="mm">${E(l.myanmarTitle)}</p><p>${E(l.summary)}</p><span class="lesson-state">${passed?'✓ Quiz passed':skills?'◐ '+skills+' skills practised':'→ Ready to start'} · ${E(l.level)}</span></div></a>`}
function skillPills(l){return `<div class="skill-checks">${SKILLS.map(s=>`<span class="${hasSkill(l,s)?'done':''}">${hasSkill(l,s)?'✓':'○'} ${E(s)}</span>`).join('')}</div>`}
function renderLesson(l,tab){if(!TABS.some(t=>t[0]===tab))tab='overview';let cur=TABS.find(t=>t[0]===tab)?.[1]||'Overview';let ix=l.id-1;
 return `<div class="page skill-area"><div class="breadcrumb"><a href="#courses/${encodeURIComponent(l.level)}">${E(l.level)} lessons</a> › Lesson ${l.id} › ${E(cur)}</div><header class="lesson-header"><div class="lesson-meta"><span class="level-pill">${E(l.level)}</span><span class="tag">LESSON ${String(l.id).padStart(2,'0')} OF ${MAX_ID}</span>${state.passed.includes(l.id)?'<span class="skill-status">✓ Quiz passed</span>':''}</div><h1>${E(l.title)}</h1><p class="mm mm-soft">${E(l.myanmarTitle)}</p><p>${E(l.focus||l.summary)}</p>${skillPills(l)}</header><nav class="skills-tabs" aria-label="Lesson activities">${TABS.map(([key,label])=>`<a href="#lesson/${l.id}/${key}" ${tab===key?'aria-current="page"':''}>${E(label)}</a>`).join('')}</nav><section class="skill-card">${renderSkill(l,tab)}</section><div class="flex-bottom"><a class="btn outline" href="#lesson/${Math.max(1,l.id-1)}/overview" ${l.id===1?'style="visibility:hidden"':''}>← Previous lesson</a><a class="btn primary" href="#lesson/${Math.min(MAX_ID,l.id+1)}/overview">${l.id===MAX_ID?'Review final lesson':'Next lesson →'}</a></div></div>`}
function skillHead(name,my,description){return `<div class="eyebrow">${E(name.toUpperCase())} PRACTICE</div><h2>${E(name)} <span class="mm mm-soft">| ${E(my)}</span></h2><p class="skill-lede">${E(description)}</p>`}
function renderSkill(l,tab){if(tab==='overview')return renderOverview(l);if(tab==='reading')return renderReading(l);if(tab==='listening')return renderListening(l);if(tab==='speaking')return renderSpeaking(l);if(tab==='writing')return renderWriting(l);if(tab==='grammar')return renderGrammar(l);if(tab==='vocab')return renderVocab(l);return renderQuiz(l)}
