function renderSpeaking(l){return `${skillHead('Speaking','စကားပြောခြင်း','Speak in your own words. Record yourself if your browser allows microphone access, then listen and reflect. No artificial band score is assigned.')}
 <ol class="hint-list">${l.speak.map(s=>`<li>${E(s)}</li>`).join('')}</ol><div class="rec-box"><h3>🎙 Speaking recorder</h3><p class="muted">Optional: your browser may ask permission to use the microphone. Audio stays in this page and is not uploaded.</p><div class="toolbar-actions"><button class="btn primary" type="button" data-action="record-start">● Start recording</button><button class="btn outline" type="button" data-action="record-stop">■ Stop recording</button><button class="btn soft" type="button" data-action="speech-recognize">Try speech-to-text</button></div><p id="recordStatus" class="statline">Ready. You can also speak without recording.</p><div id="recordPlayback"></div><p class="note-small">Speech-to-text is not supported on every browser, and supported browsers may use an online speech service. It does not measure pronunciation accurately.</p></div>
 <h3>Speaking reflection <span class="mm mm-soft">| ကိုယ်တိုင်ပြန်လည်သုံးသပ်မှု</span></h3><div class="check-row"><input id="sp1" type="checkbox"><label for="sp1">I answered the prompt and gave at least one specific example.</label></div><div class="check-row"><input id="sp2" type="checkbox"><label for="sp2">I spoke at a steady pace and corrected unclear words.</label></div><div class="check-row"><input id="sp3" type="checkbox"><label for="sp3">I listened to my recording or repeated my answer aloud.</label></div><div class="toolbar-actions"><button class="btn primary" data-action="speaking-check" type="button">Mark speaking practice done</button><button class="btn outline" data-action="say" data-text="audio" type="button">Listen to sample audio</button></div><div id="speakFeedback" aria-live="polite"></div>`}
function renderWriting(l){let min=l.minWords||60,content=state.writing[l.id]||'',task=l.table;let writingType=(l.level.startsWith('IELTS')?'Exam-style practice':'Guided free writing');let minutes=l.minutes||0;
 return `${skillHead('Writing','စာရေးခြင်း','Write your own answer, save it locally, then use the checklist to revise. Word counts and checklists are not language-quality marks.')}
 <div class="sample"><div class="split"><strong>${E(writingType)}</strong><span class="tag">Target ${min}+ words</span></div><p style="margin:10px 0">${E(l.write)}</p></div>
 ${task?`<div class="table-wrap"><table class="data-table"><caption>${E(task.title)} · illustrative exercise data</caption><thead><tr>${task.headers.map(s=>`<th scope="col">${E(s)}</th>`).join('')}</tr></thead><tbody>${task.rows.map(row=>`<tr>${row.map(v=>`<td>${E(v)}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`:''}
 ${minutes?`<div class="toolbar-actions"><span class="timer" id="lessonTimer">${minutes}:00</span><button type="button" class="btn outline sm" data-action="timer-start" data-minutes="${minutes}">Start ${minutes}-minute timer</button><button type="button" class="btn outline sm" data-action="timer-pause">Pause</button><button type="button" class="btn outline sm" data-action="timer-reset" data-minutes="${minutes}">Reset</button></div>`:''}
 <label for="writingText" style="display:block;margin:15px 0 7px;font-weight:750">Your writing <span class="mm mm-soft">| သင်ရေးသားချက်</span></label><textarea id="writingText" class="writing-box" placeholder="Write your response here. Try to answer every part of the task…">${E(content)}</textarea><div class="split writing-count"><span id="wordCount">${countWords(content)} words written · target ${min}+</span><span id="draftStatus">Saved locally on this device</span></div>
 <div class="mini-divider"></div><h3>Self-review: check these four areas</h3>${['I answered every part of the question and used relevant ideas.','I organised my response into clear, connected paragraphs.','I checked word choice and avoided unnecessary repetition.','I reviewed grammar, spelling and punctuation.'].map((s,i)=>`<label class="check-row"><input type="checkbox" class="write-check" value="${i}"> ${E(s)}</label>`).join('')}
 <div class="toolbar-actions"><button type="button" class="btn primary" data-action="writing-check">Save and check my draft</button><button type="button" class="btn soft" data-action="writing-coach">Find simple improvements</button><button type="button" class="btn outline" data-action="writing-export">Download this writing</button></div><div id="writingCoach" aria-live="polite"></div><div id="writingFeedback" aria-live="polite"></div>
 ${l.level.startsWith('IELTS')?'<p class="w-note">An official IELTS Writing band requires human-style assessment against task response/achievement, coherence and cohesion, lexical resource, and grammar. This website does not pretend to grade your essay automatically.</p>':''}`}
function renderGrammar(l){let q=l.quiz.find(q=>q.skill==='Grammar')||l.quiz[3];return `${skillHead('Grammar','သဒ္ဒါ','Understand the rule, compare examples and check one targeted question.')}
 <div class="sample"><h3>${E(l.grammarLabel||'Useful grammar')}</h3><p class="mm">${E(l.explain)}</p></div><h3 style="margin-top:23px">Apply the rule</h3>${qHtml(q,'grammar-q',0)}<button class="btn primary" type="button" data-action="grammar-check">Check grammar</button><p class="note-small">Review the rule, change your answer and try again. One question is practice, not proof of full grammar mastery.</p>`}
function cardId(l,i){return `${l.id}:${i}`}
function renderVocab(l){return `${skillHead('Vocabulary','ဝေါဟာရ','Learn five useful items. Listen, reveal the meaning, then choose “I knew it” or “Review again”. The review schedule is stored locally.')}
 <div class="vocab-grid">${l.words.map(([word,mm,example],i)=>`<article class="vocab-tile"><div><span class="tag">WORD ${i+1}</span><h3>${E(word)}</h3><div id="vocabMeaning${i}" hidden><p class="mm mm-soft">${E(mm)}</p><p>${E(example)}</p></div></div><div class="vocab-actions"><button type="button" class="btn outline sm" data-action="vocab-flip" data-idx="${i}">Reveal</button><button type="button" class="btn soft sm" data-action="vocab-audio" data-idx="${i}">🔊</button><button type="button" class="btn primary sm" data-action="vocab-rate" data-idx="${i}" data-grade="good">I knew it</button><button type="button" class="btn outline sm" data-action="vocab-rate" data-idx="${i}" data-grade="again">Review again</button></div></article>`).join('')}</div><div class="toolbar-actions"><a class="btn soft" href="#review">Open spaced review →</a></div><p class="note-small">Review timing is a simple practice reminder, not a validated measurement of memory or fluency.</p>`}
function renderQuiz(l){return `${skillHead('Lesson checkpoint','သင်ခန်းစာစစ်ဆေးမှု','Five objective questions. Score 4/5 to save quiz completion. Retake as often as you like.')}
 <div class="notice">This quiz checks selected reading, listening, grammar and vocabulary points. <strong>Speaking and writing quality are not automatically scored.</strong></div><div id="quizArea">${l.quiz.map((q,i)=>qHtml(q,'quiz'+i,i)).join('')}</div><div class="toolbar-actions"><button type="button" class="btn primary" data-action="quiz-submit">Check all five answers</button><button type="button" class="btn outline" data-action="quiz-retry">Try again</button></div><div id="quizResult" aria-live="polite"></div>`}
function dueCards(){let upper=Math.max(1,...state.visited.map(Number).filter(n=>n<=MAX_ID),...state.passed);let pool=LESSONS.filter(l=>l.id<=upper).flatMap(l=>l.words.map(([word,mm,example],i)=>({id:cardId(l,i),lesson:l.id,word,mm,example})));
 let d=today();return pool.filter(x=>!state.cards[x.id]||state.cards[x.id].due<=d).sort((a,b)=>{
  const aa=state.cards[a.id],bb=state.cards[b.id];if(aa&&!bb)return -1;if(!aa&&bb)return 1;return (a.lesson-b.lesson)
 });}
function renderReview(){let due=dueCards(),allReviewed=Object.keys(state.cards).length;if(!due.some(x=>x.id===activeFlash?.id))activeFlash=due[0]||null;
 return `<div class="page"><div class="eyebrow">SPACED REPETITION • ပြန်လည်လေ့ကျင့်ခြင်း</div><h1>Make vocabulary stick.</h1><p class="muted">Try to remember the Burmese meaning and make an English sentence before revealing the answer.</p><div class="metrics"><div class="metric"><strong class="value">${due.length}</strong><span class="label">Cards ready today</span></div><div class="metric"><strong class="value">${allReviewed}</strong><span class="label">Cards reviewed at least once</span></div><div class="metric"><strong class="value">${new Set(Object.keys(state.cards).map(k=>k.split(':')[0])).size}</strong><span class="label">Lessons with card activity</span></div><div class="metric"><strong class="value">${state.studyDates.length}</strong><span class="label">Study days</span></div></div>
 ${activeFlash?renderFlash(activeFlash):`<article class="panel empty"><h2>You're caught up for now! ✓</h2><p>Open a new lesson and practise its vocabulary, or come back when cards are due.</p><a class="btn primary" href="#courses">Explore lessons</a></article>`}
 <div class="panel"><h3>How review scheduling works</h3><p>“I knew it” schedules your next review in roughly 1, 3, 7 or 14 days as you progress. “Review again” brings the word back today. It is a simple practice system, not a prediction of permanent memory.</p></div></div>`}
function renderFlash(c){return `<div class="review-flash" id="reviewFlash"><span class="eyebrow">LESSON ${c.lesson} · WORD PRACTICE</span><h2>${E(c.word)}</h2><div id="flashBack" hidden><p class="mm" style="font-size:1.2rem">${E(c.mm)}</p><p>${E(c.example)}</p></div><div class="toolbar-actions" style="justify-content:center"><button type="button" class="btn outline" data-action="flash-flip">Reveal meaning</button><button type="button" class="btn soft" data-action="flash-audio">🔊 Listen</button><button type="button" class="btn primary" data-action="flash-grade" data-grade="good">I knew it</button><button type="button" class="btn outline" data-action="flash-grade" data-grade="again">Review again</button></div></div><p style="text-align:center" class="note-small">This card is from <a href="#lesson/${c.lesson}/vocab">Lesson ${c.lesson}</a>.</p>`}

function gymPick(level){let pool=LESSONS.filter(l=>level==='all'||l.level===level).map(l=>({ ...l.quiz.find(q=>q.skill==='Grammar'),lesson:l.id,topic:l.title})).filter(x=>x.q);
 for(let i=pool.length-1;i>0;i--){let j=Math.floor(Math.random()*(i+1));[pool[i],pool[j]]=[pool[j],pool[i]]}return pool.slice(0,Math.min(10,pool.length))}
function renderGym(level){gymLevel=TRACKS.some(t=>t[0]===level)?level:'all';if(!gymQuestions.length)gymQuestions=gymPick(gymLevel);return `<div class="page"><span class="eyebrow">EXTRA PRACTICE • သဒ္ဒါထပ်လေ့ကျင့်ခြင်း</span><h1>Grammar Gym</h1><p class="muted">Ten mixed questions with explanations, drawn from 54 grammar patterns across the course. Change the level to target one stage. Repeat with a fresh set to practise retrieval.</p><div class="toolbar"><select class="filter" id="gymLevel" aria-label="Grammar level"><option value="all">Mixed — all levels</option>${TRACKS.map(x=>`<option value="${E(x[0])}" ${gymLevel===x[0]?'selected':''}>${E(x[0])} — ${E(x[1])}</option>`).join('')}</select><button class="btn outline" type="button" data-action="gym-new">↻ New question set</button></div><div id="gymArea">${gymQuestions.map((q,i)=>`<div class="mock-question"><p class="statline">From Lesson ${q.lesson}: ${E(q.topic)}</p>${qHtml(q,'gym'+i,i)}</div>`).join('')}</div><div class="toolbar-actions"><button class="btn primary" type="button" data-action="gym-check">Check my answers</button></div><div id="gymResult" aria-live="polite"></div><p class="note-small">One short question cannot validate mastery of a grammar topic. If you missed one, revisit the related lesson and create three original examples.</p></div>`}
function renderGymInPlace(){document.getElementById('app').innerHTML=renderGym(gymLevel)}
function checkGym(){let result=scoreQuestions(gymQuestions,'gym');let el=document.getElementById('gymResult');if(result.missing){el.innerHTML=`<div class="result-banner fail">Answer all ${gymQuestions.length} questions first. ${result.missing} missing.</div>`;return}el.innerHTML=`<div class="result-banner">${result.score}/${gymQuestions.length} answered correctly. Review each explanation and try a fresh set.</div>`;toast('Grammar practice checked.')}

function renderIELTS(){return `<div class="page"><span class="eyebrow">IELTS PRACTICE STUDIO</span><h1>Prepare with the right test.</h1><p>Choose Academic or General Training. The two tests share listening and speaking formats, but their reading content and Writing Task 1 requirements differ.</p><div class="cards" style="grid-template-columns:repeat(auto-fit,minmax(270px,1fr))"><article class="panel"><span class="level-pill purple">IELTS Academic</span><h2>University and academic contexts</h2><p>Academic-style passages, chart/process description and essay tasks.</p><div class="toolbar-actions"><a href="#courses/IELTS%20Academic" class="btn primary">6 guided lessons</a><button class="btn outline" data-action="mock-start" data-type="IELTS Academic">20-minute mini check</button></div></article><article class="panel"><span class="level-pill purple">IELTS General Training</span><h2>Everyday and workplace contexts</h2><p>General-style passages, formal/informal letters and essay tasks.</p><div class="toolbar-actions"><a href="#courses/IELTS%20General" class="btn primary">6 guided lessons</a><button class="btn outline" data-action="mock-start" data-type="IELTS General">20-minute mini check</button></div></article></div>
 <div class="panel"><h2>Writing task reminder</h2><div class="sample-grid"><div class="tiny-panel"><h4>Academic Task 1</h4><p>Describe visual information such as a graph, table or process. At least 150 words; about 20 minutes.</p></div><div class="tiny-panel"><h4>General Training Task 1</h4><p>Write a letter responding to a situation. At least 150 words; about 20 minutes.</p></div><div class="tiny-panel"><h4>Task 2 (both)</h4><p>Write an essay responding to an argument or problem. At least 250 words; about 40 minutes.</p></div><div class="tiny-panel"><h4>Speaking (both)</h4><p>Practice personal questions, a long turn and deeper discussion. Genuine scoring requires skilled human assessment.</p></div></div><p class="note-small" style="margin-top:17px">Official guidance: <a href="https://ielts.org/take-a-test/test-types/ielts-academic-test/ielts-academic-format-writing" target="_blank" rel="noopener noreferrer">Academic writing</a> · <a href="https://ielts.org/take-a-test/test-types/ielts-general-training-test/ielts-general-training-format-writing" target="_blank" rel="noopener noreferrer">General Training writing</a>. These links require internet.</p></div>
 <div class="notice amber"><strong>About the mini checks:</strong> These are original 12-question, 20-minute reading-and-listening practice sets, <em>not</em> full-length IELTS mock examinations. Browser-generated audio does not replicate the actual listening test. Objective scores are not IELTS bands.</div>${state.mockResults.length?`<div class="panel"><h3>Recent practice results</h3>${state.mockResults.slice(-5).reverse().map(x=>`<p>${E(x.type)} · ${x.score}/${x.total} objective answers · ${E(x.date)}</p>`).join('')}</div>`:''}</div>`}
function renderMock(type){if(type!=='IELTS Academic'&&type!=='IELTS General')return renderIELTS();if(!state.activeMock||state.activeMock.type!==type)return `<div class="page"><h1>${E(type)} mini check</h1><p>This check has twelve original objective questions and a 20-minute timer. It is not a full IELTS mock examination.</p><button class="btn primary" data-action="mock-start" data-type="${E(type)}">Begin practice check</button></div>`;
 let mock=state.activeMock,ls=levelLessons(type),elapsed=Math.floor((Date.now()-mock.startedAt)/1000),remaining=Math.max(0,1200-elapsed);
 return `<div class="page"><a class="back-link" href="#ielts">← Back to IELTS Lab</a><span class="eyebrow">ORIGINAL TIMED PRACTICE • NOT A FULL IELTS EXAM</span><h1>${E(type)} · 12 questions</h1><p class="muted">Read each short text for its reading item. For listening items, click Play audio and answer from what you hear. The transcript is not shown during the exercise.</p>
 <div id="mockItems">${ls.map((l,k)=>`<section class="panel"><span class="level-pill">SECTION ${k+1}</span><h3>${E(l.title)}</h3><h4>Reading passage</h4><p>${E(l.reading)}</p>${qHtml(l.quiz[0],'mock'+(k*2),k*2)}<div class="mini-divider"></div><h4>Listening item</h4><button type="button" class="btn soft sm" data-action="mock-audio" data-lesson="${l.id}">🔊 Play section ${k+1} recording</button>${qHtml(l.quiz[2],'mock'+(k*2+1),k*2+1)}</section>`).join('')}</div><div class="mock-tools"><div><span class="timer" id="mockTimer">${Math.floor(remaining/60).toString().padStart(2,'0')}:${(remaining%60).toString().padStart(2,'0')}</span><span class="note-small"> · 20-minute recommended limit</span></div><button type="button" class="btn primary" data-action="mock-submit">Submit 12 answers</button></div><div id="mockResult" aria-live="polite"></div></div>`}
function renderGuide(){return `<div class="page"><span class="eyebrow">YOUR LEARNING HANDBOOK</span><h1>Practice effectively, not just often.</h1><p class="muted mm">အောက်ပါနည်းလမ်းများက ဖတ်၊ နားထောင်၊ ပြော၊ ရေး၊ သဒ္ဒါ၊ ဝေါဟာရကို စနစ်တကျ လေ့ကျင့်နိုင်ဖို့ ကူညီပါတယ်။</p><div class="cards" style="grid-template-columns:repeat(auto-fit,minmax(260px,1fr))">${[
 ['📖 Reading','Read once for the main idea, again for details. Underline where each answer is supported.','မေးခွန်းကို မှန်းဆမဖြေဘဲ စာပိုဒ်ထဲက အထောက်အထားနဲ့ ဖြေပါ။'],
 ['🎧 Listening','Predict the answer type. Listen twice at different speeds; then do dictation and compare.','နားထောင်ပြီး ရေးကြည့်ပါ။ ပြီးမှ စာသားနှင့် တိုက်စစ်ပါ။'],
 ['🎙 Speaking','Speak for one minute, record yourself, listen back and repeat with one improvement.','အသံသွင်း၊ ပြန်နားထောင်ပြီး မှားရာတစ်ခုကို ပြင်ပါ။'],
 ['✍ Writing','Plan → draft → revise. Check task coverage, paragraphs, vocabulary and grammar.','ရေးမီ အစီအစဉ်ဆွဲပြီး စာပိုဒ်ခွဲရေး၊ ပြန်စစ်ပါ။'],
 ['🧩 Grammar','Understand one pattern, create three original sentences, then correct your own mistakes.','ပုံစံတစ်ခုကို နားလည်ပြီး ကိုယ့်ဝါကျ သုံးကြောင်းရေးကြည့်ပါ။'],
 ['🗂 Vocabulary','Recall meanings before revealing them. Review difficult words after one day and again later.','စကားလုံးကို မကြည့်ဘဲ မှတ်မိအောင် ပြန်ခေါ်ပြီး ပုံမှန်ပြန်လေ့ကျင့်ပါ။']
 ].map(([a,b,c])=>`<article class="card"><h3>${E(a)}</h3><p>${E(b)}</p><p class="mm mm-soft">${E(c)}</p></article>`).join('')}</div>
 <div class="panel"><h2>CEFR-level roadmap</h2><p><strong>A1–A2:</strong> useful phrases, daily life, time, travel, basic grammar and conversations. <strong>B1:</strong> narratives, explanations, requests and practical work communication. <strong>B2:</strong> arguments, evidence, data and professional discussion. <strong>C1:</strong> nuance, synthesis, critical reading and advanced expression. <strong>IELTS Bridge:</strong> exam question types, strategies, essay structure and spoken long turns.</p><p class="note-small">These are learning themes aligned broadly to increasing language complexity, not complete CEFR-certified curricula. Independent level assessment and additional authentic listening/reading remain valuable.</p></div>
 <div class="panel"><h2>British voice preferences</h2><p>Click <strong>🔊 Voices</strong> in the header to choose a male or female British English voice, preview voices available on your device and save your preference.</p><p class="mm">British English အမျိုးသား၊ အမျိုးသမီး အသံကို အပေါ်ဘက် <strong>Voices</strong> ခလုတ်မှာ ရွေးနိုင်ပါတယ်။</p><button type="button" class="btn outline" data-action="voice-open">Open voice settings</button></div>
 <div class="panel"><h2>Protect and move your progress</h2><p>Data is stored inside your browser on this computer only. No sign-in, server or subscription is required. Export your backup regularly; restore it if you change browser or move computers.</p><div class="toolbar-actions"><button type="button" class="btn primary" data-action="progress-export">⬇ Export progress (.json)</button><button type="button" class="btn outline" data-action="progress-import">⬆ Import progress</button><button type="button" class="btn danger" data-action="progress-reset">Reset progress</button></div><p class="note-small">Never import a progress file from someone you do not trust. Import replaces locally saved progress after confirmation.</p></div>
 <div class="notice amber"><strong>Technical limitations:</strong> This free version runs by opening <code>index.html</code> in your browser. Audio uses available system/browser voices. Microphone or speech recognition may be restricted, need permission or internet, and may not be supported on every browser. All exercises remain usable without those optional features. Writing feedback is self-review only; no automated IELTS band prediction is provided.</div>
 <div class="panel"><h2>About IELTS practice</h2><p>The original IELTS-style exercises on this website are educational approximations. The official IELTS listening, reading, writing and speaking tests are longer and more demanding. For your readiness, also use official sample materials, real-time full-length practice, and teacher feedback on writing and speaking.</p><p><a href="https://ielts.org/take-a-test/preparation-resources" target="_blank" rel="noopener noreferrer">IELTS official preparation resources ↗</a></p></div></div>`}
function getPicked(name){let v=document.querySelector(`input[name="${name}"]:checked`);return v===null?null:Number(v.value)}
function paintAnswer(name,q,v){let box=document.querySelector(`[data-feedback="${name}"]`);if(!box)return;let correct=(v===q.a),answer=q.options[q.a];box.innerHTML=`<div class="answer ${correct?'':'bad'}"><strong>${correct?'✓ Correct':'✗ Not quite'}.</strong> ${E(q.why)}<br><span class="note-small">Answer: ${E(answer)}</span></div>`;return correct}
function scoreQuestions(list,prefix){let score=0,missing=0;list.forEach((q,i)=>{let name=prefix+i,v=getPicked(name);if(v===null){let target=document.querySelector(`[data-feedback="${name}"]`);if(target)target.innerHTML='<div class="answer bad">Choose an answer first.</div>';missing++;return}if(paintAnswer(name,q,v))score++});return {score,missing}}
function checkReading(){let l=currentLesson();if(!l)return;let r=scoreQuestions(l.readingQuestions,'rd');if(r.missing===0){markSkill(l,'Reading');toast(`Reading checked: ${r.score}/2. Review any mistakes.`)}else toast('Please answer both reading questions.')}
function checkGrammar(){let l=currentLesson(),q=l.quiz.find(q=>q.skill==='Grammar');let v=getPicked('grammar-q');if(v===null){toast('Choose a grammar answer first.');return}paintAnswer('grammar-q',q,v);markSkill(l,'Grammar');toast('Grammar practice saved. Review the rule and retry if needed.')}
function checkListening(){let l=currentLesson(),v=getPicked('listening-q'),dict=document.getElementById('dictInput').value;if(v===null||!norm(dict)){toast('Answer the listening question and type the dictation.');return}paintAnswer('listening-q',l.audioQuestion,v);let a=norm(l.dictation).split(' '),b=norm(dict).split(' '),matched=0;let dp=Array.from({length:b.length+1},()=>0);for(let i=1;i<=a.length;i++){let next=[0];for(let j=1;j<=b.length;j++)next[j]=a[i-1]===b[j-1]?dp[j-1]+1:Math.max(dp[j],next[j-1]);dp=next}matched=dp[b.length];let pct=percent(matched,Math.max(a.length,b.length));document.getElementById('dictFeedback').innerHTML=`<div class="answer"><strong>Dictation word match: about ${pct}%</strong><p>Expected: ${E(l.dictation)}</p><p>This is an approximate word comparison, not an official listening score. Notice any missing, extra or changed words.</p></div>`;document.getElementById('listenTranscript').hidden=false;markSkill(l,'Listening');toast('Listening practice saved.')}
function checkQuiz(){let l=currentLesson();if(!l)return;let r=scoreQuestions(l.quiz,'quiz');let text=document.getElementById('quizResult');if(r.missing){text.innerHTML=`<div class="result-banner fail">Answer all five questions first. You have ${r.missing} unanswered.</div>`;return}state.scores[l.id]=Math.max(Number(state.scores[l.id]||0),r.score);if(r.score>=4&&!state.passed.includes(l.id))state.passed.push(l.id);save();updateAside();text.innerHTML=`<div class="result-banner ${r.score>=4?'':'fail'}">${r.score}/5 · ${r.score>=4?'✓ Quiz passed and saved!':'Review the explanations and try again. You need 4/5 to pass.'}</div><p>Quiz completion means you passed these five questions; keep practising the other skills.</p>`;toast(`Lesson ${l.id} quiz: ${r.score}/5`)}
function currentLesson(){let parts=decodeURIComponent(location.hash.replace(/^#/,'' )).split('/');return parts[0]==='lesson'?tr(parts[1]):null}
/* Learner voice preference is intentionally separate from quiz progress. */
const VOICE_PREF_KEY='bea-voice-settings-v1';
let voicePreferences={gender:'male',voiceId:''};
try{
 let savedVoice=JSON.parse(localStorage.getItem(VOICE_PREF_KEY)||'null');
 if(savedVoice&&typeof savedVoice==='object'){
  if(['male','female'].includes(savedVoice.gender))voicePreferences.gender=savedVoice.gender;
  if(typeof savedVoice.voiceId==='string'&&savedVoice.voiceId.length<1500)voicePreferences.voiceId=savedVoice.voiceId;
 }
}catch(e){/* Voice controls work without saved settings. */}
function saveVoicePreferences(){try{localStorage.setItem(VOICE_PREF_KEY,JSON.stringify(voicePreferences))}catch(e){}}
function voiceIsBritish(v){return /^en[-_]GB$/i.test(v.lang)}
function voiceGenderHint(v){
 const n=v.name||'';
 if(/\b(ryan|george|daniel|david|james|oliver|guy|mark|alfie|thomas|arthur|brian|male)\b/i.test(n))return 'male';
 if(/\b(sonia|libby|hazel|kate|susan|emily|charlotte|emma|olivia|amy|jenny|serena|female)\b/i.test(n))return 'female';
 return '';
}
function voiceIsNatural(v){return /\b(natural|neural|premium|enhanced)\b/i.test(v.name||'')}
function voiceId(v){return [v.voiceURI||'',v.name||'',v.lang||''].join('||')}
function allEnglishVoices(){
 if(!('speechSynthesis'in window))return [];
 return (speechSynthesis.getVoices()||[]).filter(v=>/^en(?:[-_]|$)/i.test(v.lang)).slice().sort((a,b)=>
    Number(voiceIsBritish(b))-Number(voiceIsBritish(a))||
    Number(voiceIsNatural(b))-Number(voiceIsNatural(a))||
    (a.name||'').localeCompare(b.name||''));
}
function resolveVoice(){
 const voices=allEnglishVoices();
 const british=voices.filter(voiceIsBritish);
 const pool=british.length?british:voices;
 const chosen=voices.find(v=>voicePreferences.voiceId===voiceId(v))||null;
 const genderMatches=pool.filter(v=>voiceGenderHint(v)===voicePreferences.gender);
 const voice=chosen||genderMatches[0]||pool[0]||null;
 return {voice,voices,manual:!!chosen,hasBritish:!!british.length,hasPreferredBritish:british.some(v=>voiceGenderHint(v)===voicePreferences.gender)};
}
function refreshVoicePanel(){
 const gender=document.getElementById('voiceGender'),pick=document.getElementById('voiceChoice'),status=document.getElementById('voiceStatus');
 if(!gender||!pick||!status)return;
 gender.value=voicePreferences.gender;
 const selected=resolveVoice();
 let choices='<option value="">Automatic — best available British '+voicePreferences.gender+' voice</option>';
 for(const v of selected.voices){
   let desc=(voiceIsBritish(v)?'British en-GB':'Other English '+v.lang);
   if(voiceIsNatural(v))desc+=' · Natural/Neural';
   if(voiceGenderHint(v))desc+=' · '+voiceGenderHint(v)+' (name hint)';
   choices+='<option value="'+E(voiceId(v))+'">'+E(v.name)+' — '+E(desc)+'</option>';
 }
 pick.innerHTML=choices;
 pick.value=selected.voices.some(v=>voiceId(v)===voicePreferences.voiceId)?voicePreferences.voiceId:'';
 pick.disabled=!selected.voices.length;
 document.getElementById('voicePreview').disabled=!selected.voices.length;
 if(!('speechSynthesis'in window))status.textContent='This browser has no speech synthesis support. Try Edge or Chrome.';
 else if(!selected.voice)status.textContent='English voices are not ready or not available. Please wait a moment and try again, or install British voices in your system.';
 else{
  let msg='';
  if(!selected.manual&&!selected.hasPreferredBritish)msg='No identifiable British '+voicePreferences.gender+' voice was found; using the closest available voice. ';
  else if(selected.manual&&voiceGenderHint(selected.voice)!==voicePreferences.gender)msg='Manual choice overrides the gender preference; the browser does not report voice gender. ';
  msg+='Selected: '+selected.voice.name+' — '+(voiceIsBritish(selected.voice)?'British English (en-GB)':'other English accent')+(voiceIsNatural(selected.voice)?' · Natural/Neural labelled':'')+'. Preview it to judge how it sounds.';
  status.textContent=msg;
 }
}
function playSpeech(text,slow=false,preview=false){
 if(!('speechSynthesis'in window)){toast('Text-to-speech is unavailable on this browser.');return}
 const selection=resolveVoice();
 if(!selection.voice){refreshVoicePanel();toast('English voices are not ready. Please wait or try another browser.');return}
 const synth=window.speechSynthesis;
 synth.cancel();
 const utterance=new SpeechSynthesisUtterance(String(text??''));
 utterance.voice=selection.voice;
 utterance.lang=selection.voice.lang;
 utterance.rate=preview?1:(slow?Math.max(.6,state.speed-.22):state.speed);
 utterance.pitch=1;
 synth.speak(utterance);
}
function playFor(action){let l=currentLesson();if(!l)return;let which=action?.dataset.text||'audio';if(which.endsWith('reading'))playSpeech(l.reading,which.startsWith('slow'));else playSpeech(l.audio,which.startsWith('slow'))}
function showWritingStatus(){let l=currentLesson();if(!l)return;let area=document.getElementById('writingText');if(!area)return;state.writing[l.id]=area.value;save();let words=countWords(area.value);document.getElementById('wordCount').textContent=`${words} words written · target ${l.minWords||60}+`;document.getElementById('draftStatus').textContent='Saved locally'}
function coachWriting(){let l=currentLesson();if(!l)return;showWritingStatus();let s=state.writing[l.id]||'',output=document.getElementById('writingCoach');if(!s.trim()){output.innerHTML='<div class="answer bad">Write a few sentences first to receive basic pattern suggestions.</div>';return}
 let rules=[[/\bi am agree\b/i,'Use “I agree”, not “I am agree”.'],[/\b(?:more better|more easier|more faster)\b/i,'Avoid double comparatives: better, easier or faster.'],[/\bdid(?: not|n[’\']t) went\b/i,'After did/did not, use the base form “go”.'],[/\b(?:he|she) don[’\']t\b/i,'For he/she, use “doesn’t” instead of “don’t”.'],[/\b(?:informations|advices|equipments)\b/i,'Information, advice and equipment are normally uncountable nouns.'],[/\bdiscuss about\b/i,'Usually say “discuss the topic”, without “about”.'],[/\blook forward to hear\b/i,'After “look forward to”, use -ing: “hearing”.'],[/\b(?:he|she) go to\b/i,'Check present simple: “he/she goes” for a usual activity.'],[/\bpeople is\b/i,'Use “people are” for the plural.'],[/\b(?:I|we) has\b/i,'Use “I/we have” in standard present tense.'],[/\b(?:it|he|she) have been\b/i,'Check agreement: “it/he/she has been”.'],[/\b(?:an university|a apple|an book)\b/i,'Check a/an by sound: “a university”, “an apple”, “a book”.']];
 let notes=rules.filter(([re])=>re.test(s)).map(([,msg])=>msg);let wc=countWords(s),paras=s.split(/\n\s*\n/g).filter(x=>x.trim()).length;
 if(l.level.startsWith('IELTS')&&wc>=150&&paras<=1)notes.push('Your answer appears to have one paragraph. Consider whether separate introduction, body and conclusion paragraphs would help.');
 if(!/[.!?]\s*$/.test(s.trim()))notes.push('Check that the final sentence ends with suitable punctuation.');
 let wordCount=new Map();toWords(s).forEach(w=>{w=w.toLowerCase();if(['very','good','bad','thing','things','important'].includes(w))wordCount.set(w,(wordCount.get(w)||0)+1)});for(let [w,n] of wordCount)if(n>=4)notes.push(`You repeated “${w}” ${n} times. Consider more precise wording where appropriate.`);
 if(!notes.length)notes.push('No common patterns were detected by these limited checks. Reread your answer and ask a teacher to check accuracy, coherence and task response.');
 output.innerHTML=`<div class="sample" style="margin-top:15px"><strong>Writing coach · basic pattern hints</strong><p class="note-small">${wc} words · ${paras} paragraph(s). These simple pattern checks can miss errors or raise false positives.</p><ul class="hint-list">${notes.slice(0,7).map(n=>`<li>${E(n)}</li>`).join('')}</ul></div>`}
function checkWriting(){let l=currentLesson();if(!l)return;showWritingStatus();let words=countWords(state.writing[l.id]),target=l.minWords||60,checked=document.querySelectorAll('.write-check:checked').length;let box=document.getElementById('writingFeedback');if(words<target){box.innerHTML=`<div class="answer bad">Draft saved (${words} words). Target: ${target}+ words. Continue writing before marking this station practised. Word count alone does not show writing quality.</div>`;return}if(checked<4){box.innerHTML=`<div class="answer bad">Draft saved. Please complete all four honest self-review checks first (${checked}/4).</div>`;return}markSkill(l,'Writing');box.innerHTML='<div class="answer"><strong>✓ Writing practice saved.</strong> You met the word target and completed your own review checklist. This is not an automatic quality or IELTS band assessment.</div>';toast('Writing practice saved.')}
function addDays(n){let d=new Date();d.setDate(d.getDate()+n);return [d.getFullYear(),String(d.getMonth()+1).padStart(2,'0'),String(d.getDate()).padStart(2,'0')].join('-')}
function rateCard(id,grade){let entry=state.cards[id]||{box:0};let box=grade==='good'?Math.min(4,(entry.box||0)+1):0;let wait=[0,1,3,7,14][box];state.cards[id]={box,due:addDays(wait),last:today()};save();let l=Number(id.split(':')[0]);let lesson=tr(l);if(lesson&&lesson.words.every((_,i)=>!!state.cards[cardId(lesson,i)]))markSkill(lesson,'Vocabulary')}
function refreshReview(){document.getElementById('app').innerHTML=renderReview();updateAside()}
let writerSecondsLeft=0;
function clearLessonTimer(){if(timerHandle){clearInterval(timerHandle);timerHandle=null}}
function formatSeconds(n){return `${String(Math.floor(n/60)).padStart(2,'0')}:${String(Math.max(0,n)%60).padStart(2,'0')}`}
function timerStart(n){let el=document.getElementById('lessonTimer');if(!el)return;if(!writerSecondsLeft)writerSecondsLeft=n*60;clearLessonTimer();timerEndsAt=Date.now()+writerSecondsLeft*1000;timerHandle=setInterval(()=>{writerSecondsLeft=Math.max(0,Math.ceil((timerEndsAt-Date.now())/1000));if(el)el.textContent=formatSeconds(writerSecondsLeft);if(writerSecondsLeft<=0){clearLessonTimer();toast('Writing time finished. You can still revise your answer.')}},500)}
function timerPause(){if(!timerHandle)return;writerSecondsLeft=Math.max(0,Math.ceil((timerEndsAt-Date.now())/1000));clearLessonTimer()}
function timerReset(n){clearLessonTimer();writerSecondsLeft=n*60;let el=document.getElementById('lessonTimer');if(el)el.textContent=formatSeconds(writerSecondsLeft)}
function downloadText(filename,body,mime='text/plain'){let url=URL.createObjectURL(new Blob([body],{type:mime})),a=document.createElement('a');a.href=url;a.download=filename;document.body.append(a);a.click();a.remove();setTimeout(()=>URL.revokeObjectURL(url),1000)}
async function startRecord(){let status=document.getElementById('recordStatus');if(!status)return;if(!navigator.mediaDevices?.getUserMedia||typeof MediaRecorder==='undefined'){status.textContent='Microphone recording is unavailable here. Practise aloud and use the self-review checklist instead.';return}try{let stream=await navigator.mediaDevices.getUserMedia({audio:true});recordedChunks=[];if(recordedAudioURL)URL.revokeObjectURL(recordedAudioURL);recordedAudioURL=null;recorder=new MediaRecorder(stream);recorder.ondataavailable=e=>{if(e.data.size)recordedChunks.push(e.data)};recorder.onstop=()=>{stream.getTracks().forEach(t=>t.stop());let blob=new Blob(recordedChunks,{type:recorder.mimeType||'audio/webm'});recordedAudioURL=URL.createObjectURL(blob);let parent=document.getElementById('recordPlayback');if(parent)parent.innerHTML=`<audio controls src="${E(recordedAudioURL)}" style="width:100%;margin-top:12px"></audio><p class="note-small">Recording plays in this session only; it is not uploaded or saved automatically.</p><button type="button" class="btn outline sm" data-action="record-download">⬇ Save recording</button>`;if(status)status.textContent='Recording stopped. Listen back, then complete the self-review.'};recorder.start();status.textContent='● Recording… Speak clearly, then select Stop recording.';status.classList.add('recording')}catch(e){status.textContent='Microphone permission was unavailable. You can still practise speaking without recording.'}}
function stopRecord(){if(recorder&&recorder.state==='recording')recorder.stop();let el=document.getElementById('recordStatus');if(el)el.classList.remove('recording')}
function speechRecognize(){let SR=window.SpeechRecognition||window.webkitSpeechRecognition;let el=document.getElementById('recordStatus');if(!SR){if(el)el.textContent='Speech-to-text is not supported. You can record and listen back, or practise aloud without it.';return}try{if(recogniser)recogniser.stop();recogniser=new SR();recogniser.lang='en-GB';recogniser.interimResults=false;recogniser.maxAlternatives=1;recogniser.onresult=event=>{let phrase=event.results[0][0].transcript;if(el)el.textContent='Detected words (not a pronunciation grade): '+phrase};recogniser.onerror=event=>{if(el)el.textContent='Speech recognition was unavailable: '+event.error+'. You can still practise aloud.'};recogniser.start();if(el)el.textContent='Listening to you… please speak a short sentence.'}catch(e){if(el)el.textContent='Speech recognition is unavailable in this browser.'}}
function speakingCheck(){let l=currentLesson();if(!l)return;let all=[...document.querySelectorAll('#sp1,#sp2,#sp3')].every(x=>x.checked);let el=document.getElementById('speakFeedback');if(!all){el.innerHTML='<div class="answer bad">Complete the three self-reflection checks after genuine speaking practice.</div>';return}markSkill(l,'Speaking');el.innerHTML='<div class="answer">✓ Speaking practice recorded as self-completed. An examiner or teacher is needed for reliable proficiency feedback.</div>';toast('Speaking practice noted.')}
function mockStart(type){if(!['IELTS Academic','IELTS General'].includes(type))return;state.activeMock={type,startedAt:Date.now()};save();location.hash='#mock/'+encodeURIComponent(type);route()}
let mockClock=null;
function startMockClock(){if(mockClock)clearInterval(mockClock);let el=document.getElementById('mockTimer');if(!el||!state.activeMock)return;const tick=()=>{let el=document.getElementById('mockTimer');if(!el){clearInterval(mockClock);mockClock=null;return}let rem=Math.max(0,1200-Math.floor((Date.now()-state.activeMock.startedAt)/1000));el.textContent=formatSeconds(rem);if(rem===0){clearInterval(mockClock);mockClock=null;toast('20 minutes elapsed. Submit when ready; late submissions are labelled.')}};tick();mockClock=setInterval(tick,1000)}
function submitMock(){if(!state.activeMock)return;let type=state.activeMock.type,ls=levelLessons(type).slice(0,6),questions=ls.flatMap(l=>[l.quiz[0],l.quiz[2]]);let r=scoreQuestions(questions,'mock');if(r.missing){toast(`Please complete all questions (${r.missing} unanswered).`);return}let elapsed=Math.floor((Date.now()-state.activeMock.startedAt)/1000),late=elapsed>1200;state.mockResults.push({type,score:r.score,total:12,date:today(),seconds:elapsed,late});state.activeMock=null;save();if(mockClock)clearInterval(mockClock);document.querySelector('.mock-tools').innerHTML=`<strong>Practice check complete · ${r.score}/12 · ${late?'Over the 20-minute target':'Within the 20-minute target'}</strong><a class="btn primary" href="#ielts">Back to IELTS Lab</a>`;document.getElementById('mockResult').innerHTML=`<div class="result-banner">${r.score} of 12 original questions correct. Review feedback above. This is <strong>not an IELTS band score</strong>.</div>`;toast('Mini check saved.')}
function exportProgress(){let payload={app:'Burmese English Academy',version:1,exportedAt:new Date().toISOString(),progress:state};downloadText('burmese-english-academy-progress-'+today()+'.json',JSON.stringify(payload,null,2),'application/json');toast('Progress backup downloaded.')}
async function importProgress(file){if(!file)return;try{if(file.size>3000000)throw Error('File is too large');let obj=JSON.parse(await file.text());if(obj.app!=='Burmese English Academy'||obj.version!==1||!obj.progress||!Array.isArray(obj.progress.passed))throw Error('This does not appear to be an academy progress backup');if(!confirm('Replace the locally saved progress with this backup? Your existing progress on this browser will be overwritten.'))return;let p=obj.progress,next=defaultState();next.passed=[...new Set(p.passed.map(Number).filter(n=>Number.isInteger(n)&&n>=1&&n<=MAX_ID))];next.last=Number(p.last)>0&&Number(p.last)<=MAX_ID?Number(p.last):1;for(let key of ['scores','skills','writing','cards'])if(p[key]&&typeof p[key]==='object'&&!Array.isArray(p[key]))next[key]=p[key];for(let key of ['visited','studyDates','mockResults'])if(Array.isArray(p[key]))next[key]=p[key];next.speed=[.75,.85,1].includes(Number(p.speed))?Number(p.speed):.85;state=next;save();route();toast('Progress restored.')}catch(e){toast('Could not import progress: '+e.message)}finally{document.getElementById('importFile').value=''}}
document.addEventListener('click',async function(ev){let node=ev.target.closest('[data-action]');if(!node)return;let action=node.dataset.action;if(!action)return;ev.preventDefault();const l=currentLesson();
 switch(action){
 case 'reading-check':checkReading();break;
 case 'grammar-check':checkGrammar();break;
 case 'listening-check':checkListening();break;
 case 'listen-reveal':document.getElementById('listenTranscript').hidden=false;break;
 case 'quiz-submit':checkQuiz();break;
 case 'quiz-retry':if(l)document.getElementById('app').innerHTML=renderLesson(l,'quiz');break;
 case 'say':playFor(node);break;
 case 'say-stop':if('speechSynthesis'in window)window.speechSynthesis.cancel();break;
 case 'voice-open':document.getElementById('voiceSettingsToggle').click();document.getElementById('voiceSettingsPanel').scrollIntoView({behavior:'smooth',block:'start'});break;
 case 'vocab-audio':if(l)playSpeech(l.words[Number(node.dataset.idx)]?.[0]);break;
 case 'vocab-flip':{let id=Number(node.dataset.idx),el=document.getElementById('vocabMeaning'+id);if(el){el.hidden=!el.hidden;node.textContent=el.hidden?'Reveal':'Hide'}}break;
 case 'vocab-rate':if(l){let i=Number(node.dataset.idx),key=cardId(l,i);rateCard(key,node.dataset.grade);let target=document.getElementById('vocabMeaning'+i);target.hidden=false;toast(node.dataset.grade==='good'?'Added to spaced review.':'Card scheduled for another review today.')}break;
 case 'writing-check':checkWriting();break;
 case 'writing-coach':coachWriting();break;
 case 'writing-export':if(l){let a=state.writing[l.id]||'';if(a.trim())downloadText(`academy-lesson-${l.id}-writing.txt`,l.title+'\n\n'+l.write+'\n\n'+a);else toast('Write something first.')}break;
 case 'timer-start':timerStart(Number(node.dataset.minutes));break;
 case 'timer-pause':timerPause();break;
 case 'timer-reset':timerReset(Number(node.dataset.minutes));break;
 case 'record-start':await startRecord();break;
 case 'record-stop':stopRecord();break;
 case 'record-download':if(recordedChunks.length){let b=new Blob(recordedChunks,{type:recorder?.mimeType||'audio/webm'}),url=URL.createObjectURL(b),a=document.createElement('a');a.href=url;a.download=`lesson-${l?.id||'practice'}-speaking.webm`;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}break;
 case 'speech-recognize':speechRecognize();break;
 case 'speaking-check':speakingCheck();break;
 case 'flash-flip':{let el=document.getElementById('flashBack');el.hidden=!el.hidden;node.textContent=el.hidden?'Reveal meaning':'Hide meaning'}break;
 case 'flash-audio':if(activeFlash)playSpeech(activeFlash.word);break;
 case 'flash-grade':if(activeFlash){let old=activeFlash.id;rateCard(old,node.dataset.grade);activeFlash=dueCards().find(x=>x.id!==old)||dueCards()[0]||null;refreshReview()}break;
 case 'gym-new':gymQuestions=[];renderGymInPlace();break;
 case 'gym-check':checkGym();break;
 case 'mock-start':mockStart(node.dataset.type);break;
 case 'mock-audio':{let item=tr(node.dataset.lesson);if(item)playSpeech(item.audio)}break;
 case 'mock-submit':submitMock();break;
 case 'progress-export':exportProgress();break;
 case 'progress-import':document.getElementById('importFile').click();break;
 case 'progress-reset':if(confirm('Permanently reset all local quiz progress, writing drafts, vocabulary scheduling and practice results in this browser? Please export a backup first.')){state=defaultState();save();activeFlash=null;route();toast('Local progress reset.')}break;
 }
});
document.addEventListener('input',e=>{
 if(e.target.id==='writingText')showWritingStatus();
 if(e.target.id==='courseSearch'){
  searchQuery=e.target.value;let list=LESSONS.filter(l=>(filterLevel==='all'||l.level===filterLevel)&&(`${l.title} ${l.myanmarTitle} ${l.summary} ${l.level}`).toLowerCase().includes(searchQuery.toLowerCase()));let box=document.getElementById('courseMatches');if(box)box.innerHTML=list.length?list.map(lessonTile).join(''):'<p class="empty">No lessons found. Try a different topic.</p>';
 }
});
document.addEventListener('change',e=>{
 if(e.target.id==='levelSelect'){filterLevel=e.target.value;location.hash='#courses/'+encodeURIComponent(filterLevel);route()}
 if(e.target.id==='gymLevel'){gymLevel=e.target.value;gymQuestions=[];renderGymInPlace()}
 if(e.target.id==='speedControl'){state.speed=Number(e.target.value);save();toast('Speech speed updated.')}
 if(e.target.id==='importFile')importProgress(e.target.files[0]);
});
/* Voice selection controls stay usable between lesson changes. */
document.getElementById('voiceSettingsToggle').addEventListener('click',()=>{
 const panel=document.getElementById('voiceSettingsPanel');
 panel.hidden=!panel.hidden;
 document.getElementById('voiceSettingsToggle').setAttribute('aria-expanded',String(!panel.hidden));
 if(!panel.hidden){refreshVoicePanel();document.getElementById('voiceGender').focus()}
});
document.getElementById('voiceGender').addEventListener('change',e=>{
 voicePreferences.gender=e.target.value==='female'?'female':'male';
 voicePreferences.voiceId='';
 saveVoicePreferences();refreshVoicePanel();
});
document.getElementById('voiceChoice').addEventListener('change',e=>{
 voicePreferences.voiceId=e.target.value;saveVoicePreferences();refreshVoicePanel();
});
document.getElementById('voicePreview').addEventListener('click',()=>playSpeech('Good morning! Welcome to Burmese English Academy. Let us practise clear British English together.',false,true));
document.getElementById('voiceStop').addEventListener('click',()=>{if('speechSynthesis'in window)speechSynthesis.cancel()});
document.addEventListener('keydown',e=>{
 if(e.key==='Escape'&&!document.getElementById('voiceSettingsPanel').hidden){
  document.getElementById('voiceSettingsPanel').hidden=true;
  document.getElementById('voiceSettingsToggle').setAttribute('aria-expanded','false');
  document.getElementById('voiceSettingsToggle').focus();
 }
});
